const BATCH = 50;
const MAX_BUFFER = 5000;
let buf = flow.get('buffer') || [];

if (msg.topic !== 'flush') {
    let p = msg.payload;
    if (typeof p === 'string') {
        try { p = JSON.parse(p); }
        catch (e) { node.warn('Payload no es JSON valido'); return null; }
    }
    if (p === null || typeof p !== 'object') { return null; }

    const num = v => (v === undefined || v === null || v === '' || isNaN(Number(v))) ? null : Number(v);
    const partes = (msg.topic || '').split('/');

    const row = {
        timestamp: p.timestamp ? new Date(p.timestamp).toISOString() : new Date().toISOString(),
        dispositivo: p.dispositivo || p.device || partes[1] || 'desconocido',
        linea: p.linea !== undefined ? String(p.linea) : null,
        cod_evento: num(p.cod_evento),
        estado: p.estado !== undefined ? String(p.estado) : null,
        velocidad: num(p.velocidad),
        unid_producidas: num(p.unid_producidas),
        unid_buenas: num(p.unid_buenas),
        temperatura: num(p.temperatura),
        raw: JSON.stringify(p)
    };
    buf.push(row);
    if (buf.length > MAX_BUFFER) { buf = buf.slice(buf.length - MAX_BUFFER); }
}

const enviar = (msg.topic === 'flush') ? buf.length > 0 : buf.length >= BATCH;
if (enviar) {
    flow.set('buffer', []);
    node.status({ fill: 'blue', shape: 'dot', text: 'lote de ' + buf.length });
    return { payload: buf };
}

flow.set('buffer', buf);
node.status({ fill: 'grey', shape: 'ring', text: 'buffer: ' + buf.length });
return null;

const rows = msg.payload;
if (!Array.isArray(rows) || rows.length === 0) { return null; }

const projectId = env.get('BQ_PROJECT');
const datasetId = env.get('BQ_DATASET');
const tableId = env.get('BQ_TABLE');
if (!projectId || !datasetId || !tableId) {
    node.error('Faltan variables de entorno BQ_PROJECT, BQ_DATASET o BQ_TABLE', msg);
    return null;
}

let bq = context.get('bq');
if (!bq) {
    bq = new BigQuery.BigQuery({ projectId: projectId });
    context.set('bq', bq);
}

try {
    await bq.dataset(datasetId).table(tableId).insert(rows);
    node.status({ fill: 'green', shape: 'dot', text: rows.length + ' filas insertadas' });
    return { payload: { insertadas: rows.length, tabla: projectId + '.' + datasetId + '.' + tableId } };
} catch (err) {
    if (err.name === 'PartialFailureError') {
        // Filas con datos invalidos: se descartan para no entrar en bucle de reintentos
        const detalle = JSON.stringify(err.errors || []).slice(0, 600);
        node.error('BigQuery rechazo filas: ' + detalle, msg);
        node.status({ fill: 'yellow', shape: 'ring', text: 'filas rechazadas' });
        return null;
    }
    // Error de red/credenciales: se devuelve el lote al buffer para reintentar en el proximo ciclo
    const buf = flow.get('buffer') || [];
    flow.set('buffer', rows.concat(buf).slice(0, 5000));
    node.error('BigQuery: ' + err.message, msg);
    node.status({ fill: 'red', shape: 'ring', text: 'error, se reintenta' });
    return null;
}
